WITH flagged AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT id, order_id, paid_at, session_start_flag, burst_id FROM sessionized;
